1	import { describe, it, expect } from "vitest";
2	import { nextGeneration, type Cell } from "./game-of-life.js";
3	
4	const sorted = (cells: Cell[]): Cell[] =>
5	  [...cells].sort(([ax, ay], [bx, by]) => ax - bx || ay - by);
6	
7	describe("Game of Life - Next Generation", () => {
8	  it("should return an empty grid for a single live cell with no neighbors", () => {
9	    expect(nextGeneration([[0, 0]])).toEqual([]);
10	  });
11	  it("should return an empty grid for two adjacent cells that each have one neighbor", () => {
12	    expect(nextGeneration([[0, 1], [1, 1]])).toEqual([]);
13	  });
14	  it("should keep a live cell with three live neighbors alive", () => {
15	    expect(nextGeneration([[0, 0], [1, 0], [2, 0], [1, 1]])).toContainEqual([
16	      1, 1,
17	    ]);
18	  });
19	  it("should kill a live cell with four live neighbors", () => {
20	    expect(
21	      nextGeneration([
22	        [1, 1],
23	        [0, 0],
24	        [0, 1],
25	        [0, 2],
26	        [1, 0],
27	      ]),
28	    ).not.toContainEqual([1, 1]);
29	  });
30	  it("should bring a dead cell with exactly three live neighbors to life", () => {
31	    expect(
32	      nextGeneration([
33	        [0, 0],
34	        [1, 0],
35	        [0, 1],
36	      ]),
37	    ).toContainEqual([1, 1]);
38	  });
39	  it("should turn a vertical blinker into a horizontal blinker", () => {
40	    expect(
41	      sorted(
42	        nextGeneration([
43	          [0, 0],
44	          [0, 1],
45	          [0, 2],
46	        ]),
47	      ),
48	    ).toEqual(
49	      sorted([
50	        [-1, 1],
51	        [0, 1],
52	        [1, 1],
53	      ]),
54	    );
55	  });
56	  it("should turn a horizontal blinker back into a vertical blinker", () => {
57	    expect(
58	      sorted(
59	        nextGeneration([
60	          [-1, 1],
61	          [0, 1],
62	          [1, 1],
63	        ]),
64	      ),
65	    ).toEqual(
66	      sorted([
67	        [0, 0],
68	        [0, 1],
69	        [0, 2],
70	      ]),
71	    );
72	  });
73	  it.todo("should leave a block unchanged");
74	  it.todo("should compute the next generation for cells at negative coordinates");
75	});
