1	export type Cell = [number, number];
2	
3	const NEIGHBOR_OFFSETS: Cell[] = [
4	  [-1, -1],
5	  [-1, 0],
6	  [-1, 1],
7	  [0, -1],
8	  [0, 1],
9	  [1, -1],
10	  [1, 0],
11	  [1, 1],
12	];
13	
14	const neighborsOf = ([x, y]: Cell): Cell[] =>
15	  NEIGHBOR_OFFSETS.map(([dx, dy]): Cell => [x + dx, y + dy]);
16	
17	const identityOf = ([x, y]: Cell): string => `${x},${y}`;
18	
19	const countLiveNeighbors = (cell: Cell, liveIdentities: Set<string>): number =>
20	  neighborsOf(cell).filter((neighbor) => liveIdentities.has(identityOf(neighbor)))
21	    .length;
22	
23	const withoutDuplicates = (cells: Cell[]): Cell[] => [
24	  ...new Map(cells.map((cell) => [identityOf(cell), cell])).values(),
25	];
26	
27	const candidates = (liveCells: Cell[]): Cell[] =>
28	  withoutDuplicates([...liveCells, ...liveCells.flatMap(neighborsOf)]);
29	
30	const SURVIVAL_NEIGHBOR_COUNTS = [2, 3];
31	const BIRTH_NEIGHBOR_COUNT = 3;
32	
33	const isAliveNextGeneration = (
34	  cell: Cell,
35	  liveIdentities: Set<string>,
36	): boolean => {
37	  const liveNeighbors = countLiveNeighbors(cell, liveIdentities);
38	  return liveIdentities.has(identityOf(cell))
39	    ? SURVIVAL_NEIGHBOR_COUNTS.includes(liveNeighbors)
40	    : liveNeighbors === BIRTH_NEIGHBOR_COUNT;
41	};
42	
43	export const nextGeneration = (liveCells: Cell[]): Cell[] => {
44	  const liveIdentities = new Set(liveCells.map(identityOf));
45	  return candidates(liveCells).filter((cell) =>
46	    isAliveNextGeneration(cell, liveIdentities),
47	  );
48	};
